<?php
require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/functions.php';$company=require __DIR__.'/config/company.php';$code=trim($_GET['code']??'');$c=null;$shipments=[];
if($code!==''){$s=db()->prepare('SELECT id,name,code,address FROM customers WHERE code=?');$s->execute([$code]);$c=$s->fetch();if($c){$s=db()->prepare('SELECT brand_name,jtr_number,weight,price,shipment_date,status FROM shipments WHERE customer_id=? ORDER BY shipment_date DESC,id DESC');$s->execute([$c['id']]);$shipments=$s->fetchAll();}}
$counts=array_fill_keys(array_keys(status_labels()),0);foreach($shipments as $r)$counts[$r['status']]++;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shipment Tracking · <?=e($company['company_name'])?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/style.css?v=3" rel="stylesheet"></head><body class="tracking-page"><header class="tracking-hero"><div class="container text-center"><img src="<?=e($company['logo'])?>" alt="<?=e($company['company_name'])?>"><h1 class="h3 mb-1">Shipment Tracking</h1><?php if($c):?><p class="mb-0 opacity-75"><?=e($c['name'])?> · <?=e($c['code'])?></p><?php endif;?></div></header><main class="container tracking-wrap pb-5" style="max-width:960px"><div class="card p-3 p-md-4 mb-3"><?php if(!$code):?><div class="alert alert-info mb-0">Open your personal tracking link to view shipments.</div><?php elseif(!$c):?><div class="text-center py-4"><h2 class="h4">Customer link not found</h2></div><?php else:?><input id="search" class="form-control form-control-lg mb-3" placeholder="Search by JTR Number" aria-label="Search by JTR Number"><?php if($c['address']):?><div class="small text-muted mb-3">Address: <strong><?=e($c['address'])?></strong></div><?php endif;?><div class="d-flex flex-wrap gap-2" id="filters"><button class="btn btn-sm btn-outline-secondary filter-btn active" data-filter="all">All <span class="badge text-bg-light"><?=count($shipments)?></span></button><?php foreach(status_labels() as $k=>$label):?><button class="btn btn-sm btn-outline-secondary filter-btn" data-filter="<?=e($k)?>"><?=e($label)?> <span class="badge text-bg-light"><?=e($counts[$k])?></span></button><?php endforeach;?></div><?php endif;?></div><?php if($c):?><div class="row g-3" id="shipmentList"><?php foreach($shipments as $r):?><div class="col-12 col-md-6 shipment-item" data-status="<?=e($r['status'])?>" data-jtr="<?=e(strtolower($r['jtr_number']))?>"><article class="card shipment-card p-4 h-100"><div class="shipment-brand text-center mb-1"><?=e($r['brand_name']?:$company['company_name'])?></div><h2 class="h5 fw-bold text-center mb-3"><?=e($r['jtr_number'])?></h2><div class="text-center mb-3"><span class="status-badge <?=e(status_class($r['status']))?>"><?=e(status_labels()[$r['status']])?></span></div><div class="row g-3"><div class="col-4"><small class="text-muted d-block">Weight</small><strong><?=e(rtrim(rtrim($r['weight'],'0'),'.'))?> KG</strong></div><div class="col-4"><small class="text-muted d-block">Price</small><strong><?=$r['price']!==null?e(number_format((float)$r['price'],2)):'-'?></strong></div><div class="col-4"><small class="text-muted d-block">Date</small><strong><?=e(date('d M Y',strtotime($r['shipment_date'])))?></strong></div><?php if($c['address']):?><div class="col-12 border-top pt-3"><small class="text-muted d-block">Customer Address</small><strong><?=e($c['address'])?></strong></div><?php endif;?></div></article></div><?php endforeach;?></div><div id="empty" class="card p-5 text-center text-muted <?=count($shipments)?'d-none':''?>">No shipments found.</div><?php endif;?></main><footer class="bg-white border-top py-4"><div class="container d-flex flex-column flex-md-row align-items-center justify-content-between gap-3" style="max-width:960px"><img src="<?=e($company['logo'])?>" alt="<?=e($company['company_name'])?>" height="45"><div class="text-center text-md-end"><div>Iraq: <a href="tel:<?=e(preg_replace('/[^+\d]/','',$company['iraq_phone']))?>"><?=e($company['iraq_phone'])?></a></div><div>Dubai: <a href="tel:<?=e(preg_replace('/[^+\d]/','',$company['dubai_phone']))?>"><?=e($company['dubai_phone'])?></a></div></div></div></footer><script>const items=[...document.querySelectorAll('.shipment-item')],search=document.querySelector('#search'),empty=document.querySelector('#empty');let status='all';function filter(){let shown=0,q=(search?.value||'').trim().toLowerCase();items.forEach(x=>{let on=(status==='all'||x.dataset.status===status)&&x.dataset.jtr.includes(q);x.classList.toggle('d-none',!on);shown+=on?1:0});if(empty)empty.classList.toggle('d-none',shown!==0)}search?.addEventListener('input',filter);document.querySelector('#filters')?.addEventListener('click',e=>{let b=e.target.closest('[data-filter]');if(!b)return;status=b.dataset.filter;document.querySelectorAll('.filter-btn').forEach(x=>x.classList.toggle('active',x===b));filter()});</script></body></html>
